function renderJournal(){
 if(!report)return;
 const steps=visibleSteps(),rounds=[...new Set(steps.map(g=>g.round))];
 const diagnosticByRound=groupActions(report.events).filter(g=>g.roomIndex===room&&['skip','regen'].includes(g.type));
 $('#journal').innerHTML=rounds.map(r=>`<details class="round-report" open><summary>${r===0?'进入房间':'第 '+r+' 回合'}</summary>${steps.filter(g=>g.round===r).map(g=>`<button class="journal-row" data-event="${g.start}"><small>${g.phase} · ${g.actionId?'一次完整施放':g.type==='defend'?'防御响应':'状态记录'}</small>${esc(summaryOf(g))}</button>`).join('')}${!$('#diagnostic').checked?`<details class="diagnostic-summary"><summary>跳过与自然回复（${diagnosticByRound.filter(g=>g.round===r).length} 条）</summary>${diagnosticByRound.filter(g=>g.round===r).map(g=>`<p>${esc(g.events[0].text)}</p>`).join('')}</details>`:''}</details>`).join('');
}
