document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
$('#save-a').onclick=()=>{savedA=clone(config);try{localStorage.setItem(storageKey+'-a',JSON.stringify(savedA));}catch{}planner();tell('方案 A 已冻结。现在调整一项设置，再运行对照。');};
$('#compare-run').onclick=()=>{if(!savedA){tell('请先保存方案 A。');return;}try{if(savedA.expedition!==config.expedition)throw Error('A 与 B 的远征路线不同，请先切换至相同路线再对照。');const a=clone(savedA);a.seed=config.seed;pair=[run(a),run()];const metrics=r=>[r.rooms.filter(x=>x.won).length,r.party.filter(u=>u.hp>0).length,r.party.reduce((s,u)=>s+u.hp,0),r.party.reduce((s,u)=>s+u.mp,0),Object.values(r.stats).filter(s=>!s.owner||HEROES.some(h=>h.id===s.owner)).reduce((s,u)=>s+u.defenseMana,0),Object.values(r.stats).filter(s=>!s.owner||HEROES.some(h=>h.id===s.owner)).reduce((s,u)=>s+u.healing,0),Object.values(r.stats).filter(s=>!s.owner||HEROES.some(h=>h.id===s.owner)).reduce((s,u)=>s+u.interrupts,0),Object.values(r.stats).filter(s=>!s.owner||HEROES.some(h=>h.id===s.owner)).reduce((s,u)=>s+u.failed,0),r.events.find(e=>e.type==='effect'&&e.detail.scope==='rounds'&&e.text.includes('潮纹屏障'))?.detail.value??'未施放',r.supplies.herb,r.supplies.rune,r.supplies.arrow,r.config.expedition==='harbor'?r.rooms.map(x=>x.name).join(' → '):(BELL_ROUTES[r.events.find(e=>e.type==='route')?.detail.route]?.name||'无分支记录')];const ma=metrics(pair[0]),mb=metrics(pair[1]);$('#comparison').innerHTML=`<h3>共同种子 ${config.seed}</h3><table><thead><tr><th>观察项</th><th>方案 A</th><th>当前 B</th></tr></thead><tbody>${['通过房间','存活队员','剩余生命','剩余法力','防御消耗法力','有效治疗','治疗中断次数','空过行动','首次屏障强度','剩余药草','剩余符纸','剩余箭矢','实际末房路线'].map((k,i)=>`<tr><td>${k}</td><td>${ma[i]}</td><td>${mb[i]}</td></tr>`).join('')}</tbody></table><button data-open-pair="0">打开 A 战报</button> <button data-open-pair="1">打开 B 战报</button><p class="muted">同种子便于复现，不保证修改行动后各检定仍使用同一随机数。单次胜负不能证明方案普遍更强。</p>`;$('#comparison').insertAdjacentHTML('beforeend',comparisonDetails(pair));tell('对比完成。');}catch(e){pair=null;$('#comparison').innerHTML='<p>'+esc(e.message)+'</p>';tell(e.message);}};
$('#comparison').onclick=e=>{const b=e.target.closest('[data-open-pair]');if(b)loadReport(pair[Number(b.dataset.openPair)]);};
$('#rules').onclick=()=>{$('#modal-body').innerHTML=`<p class="eyebrow">规则边界 / 0.57</p><h2>用明确规则验证协作</h2><p>本版是自主实现的 WoD 灵感原型。第三方 wod_local 提供结构参考，没有复制其代码，也不宣称所有公式符合原版。</p><h3>当前结算顺序</h3><p>回合开始 / 延迟效果激活 → 回合前行动 → 法力回复 → 先攻与行动队列 → 道具检查 / 治疗检查 / 普通行动 → 效果到期。</p><h3>属性与修正</h3><p>检定均值：主属性 ×2 + 副属性 + 技能等级 ×2。基础伤害：主属性 ÷2 + 副属性 ÷3 + 技能等级 ÷2。装备和临时属性效果先作用于属性；战技传授作用于攻击技能等级。</p><h3>明确采用原创规则的部分</h3><p>投点使用两个均匀随机值形成三角分布；先攻衰减为 1 / (1 + 0.6 × 已排行动数)。重击 / 致命倍率为 1.25 / 1.5，固定护甲扣除后，再乘以（1−类型抗性/100）并向下取整。负抗性表示弱点；闪避不造成伤害。抗性按近战、远程、法术区分，当前仅封库敌人有非零抗性，不是WoD原版伤害分类。伤势阈值由玩家选择；这些都不是经原版验证的公式。</p><h3>防御与多阶段效果</h3><p>防御检定遵循对应主属性×2+副属性+技能等级×2。自然防御技能等级为0；近战使用灵巧/敏捷、远程使用敏捷/感知、法术使用意志/智力。防御技能费用、基础等级6级和专修+3级是原创规则，缺少装备或法力时回退自然防御。延迟从生效时开始计算持续时间；同名效果有任一组件尚在等待或生效时不会重复施加。</p><h3>目标与效果</h3><p>近战按站位路线选择；远程和法术优先指定位置，无人时转移。群攻不会跨位置补齐。同名增益在目标身上互斥。持续 N 回合指当前与之后 N 回合。房间效果进场前结束，药膳持续整次远征。</p><h3>指令节奏</h3><p>普通指令的每回合一次按指令条目计数，成功施放含闪避后本回合不重试；未满足装备、资源或目标条件不计次数。带有该模式的普通阶段在本人本回合首次检查普通指令时从第一条开始，额外行动沿游标继续后备，下回合重新检查；仍受道具和救护优先级限制。仅配置一条且已经执行时，后续机会可能空过，请保留低耗后备。</p><h3>独立后期职业进阶</h3><p>本项目在累计300经验且公会通关资深试炼后，为六职业分别开放两个独立研修方向；选择支付80经验，当前退回返还80。进阶不删除、锁定或排斥普通技能。实验草稿可试配，公会实际出征采用个人已选择进阶。门槛和数值是项目参数，不宣称原版21级或现行服务器规则。</p><h3>缓释药敷</h3><p>药师可在预备阶段消耗4法力、1药草，覆盖同阵位最多3人；下一及再下一回合开始基础各恢复8生命。同名效果等待或生效时不叠加，不复活，不占普通行动；回合开始先激活延迟效果、再缓释恢复，然后执行预备。它不受只限制自动草药救护的禁疗影响。固定恢复量不因技能等级增长，不能取代当回合救急。</p><h3>截疗与先后手</h3><p>学者可选截疗符：6法力、1符纸、需法器，低伤害单体法术。命中仍存活且有救护技能的目标后，仅限制其本回合余下的自动草药救护，回合结束解除；闪避不附着，伤害吸收不阻止附着。同回合不叠加或延长，重复攻击仍付费。目标仍能执行普通指令、使用随身道具；已完成的治疗不撤销。附着次数不等于阻止救护次数，先攻与时机决定是否来得及。该效果敌我一致，默认队伍不启用。</p><h3>训练与装备条件</h3><p>每项永久训练最多额外+3级，逐级消耗20/40/60经验，没有全角色6点硬上限。公会经验不足时不能培养，实验草稿不扣经验。训练跨房间共用，原有专修保留。专修+3是本原型的战前加成，不是精通门槛或职业进阶，也不排斥其他普通技能。技能等级进入命中、伤害、辅助或召唤公式；固定数值辅助不会因训练自动增强。自然防御不吃训练等级。盾缘重击需要盾甲类装备，破甲重箭需要弓具类装备，凝潮长枪需要法器类装备；缺少装备时不扣费并尝试下一条指令。破甲只在本次命中计算时忽略部分护甲，不修改目标装备。</p><h3>断潮封库</h3><p>独立挑战：战前最多24份共享物资，每房5回合，拾取药草占第二房间1回合，该房剩4回合。截止时未清场即失败；原有路线与敌人不变。</p><h3>回廊救援</h3><p>封库第二房间进场先救援、后沉钟：赶路无收益；拾取固定获得2药草；救治消耗3药草，存活药师治疗检定难度70，成功获得4符纸和4箭矢，失败仍耗药草。救援使用独立随机流，无额外法力和行动费用，不复活角色、不计战斗治疗。普通路线战前60份、断潮挑战24份、守灯归途36份是携带预算，途中获取可超过该预算。</p><h3>非战斗机关</h3><p>封库试炼第2房间进场、回合前之前自动执行战前选定的机关策略。按当前存活、装备和技能均值择优；不支付该战斗技能本身的法力费用，只支付事件标明的补给。独立种子检定，不消耗战斗随机数序列。未满足条件或补给不足则绕过、不付费。成功增益只给予当前存活正式队员，房间结束清除；失败扣执行者最多12法力。插画不决定结果。解读成功会令末房全体敌人法术抗性降低20个百分点；破拆成功绕过后排护印师，但三名守印者力量+4。路线效果在抵达末房时生效，无额外收费与检定，战报可追溯来源。</p><h3>当前范围</h3><p>五个战斗位置、六人出战与两名可招募候补，多条路线及六场连续章节。已实现独立防御、延迟多组件效果和按房间覆盖。已加入召唤物、每件道具独立次数及潮汐异变挑战；已实现个人成长、固定属性装备掉落和武器／防具／饰品三部位配装；自由探索分支尚未实现。召唤物本房间有效，主人倒下时消散；正式队员全灭即失败。随身道具占用普通行动并保持指令游标，次数跨房间保留。立绘样片使用 AI 生成，弹道和反馈由结算事件驱动；碎印阶段使用预生成CG，仅在对应事件触发时显示；未接入在线CG生成。v0.9新增镜潮回廊场景、固定阵位展示和跨房间连续回放；阵位布局是逻辑位置的可视化，不代表距离、移动或碰撞规则。演出只读取原始战报，不再投骰或改写结果。</p><p><a href="https://github.com/dust1/wod_local" target="_blank" rel="noreferrer">第三方参考项目 ↗</a></p>`;$('#modal').showModal();};$('#close').onclick=()=>$('#modal').close();
planner();persist();

function loadCase(kind){undoConfig=configurationUndo(config);savedA=defaults();config=defaults();scope='';if(kind==='bell'){savedA=archiveConfig();config=clone(savedA);config.bellApproach='study';}if(kind==='archive'){savedA=archiveConfig();config=archiveConfig(true);}if(kind==='training'){savedA=trainingBuild('support');config=trainingBuild('defense');}if(kind==='pierce'){savedA=trainingBuild();config=clone(savedA);config.heroes.find(h=>h.id==='b').main[0]=row('pierce','rear');}if(kind==='shortage'){savedA=challengeConfig();savedA.supplies.arrow=0;savedA.heroes.find(h=>h.id==='b').main=[row('volley','rear')];config=clone(savedA);config.heroes.find(h=>h.id==='b').main.push(row('shot','rear'));}if(kind==='summon'){savedA=challengeConfig();config=clone(savedA);savedA.heroes.find(h=>h.id==='c').prep=[];}if(kind==='item'){savedA=challengeConfig();config=clone(savedA);for(const h of savedA.heroes)h.item='none';}if(kind==='defense'){for(const h of savedA.heroes)h.defenses={melee:'natural',ranged:'natural',magic:'natural'};for(const h of config.heroes)h.defenses={melee:h.id==='a'?'parry':'sidestep',ranged:'dodge',magic:'resist'};}
 if(kind==='delay'){config.heroes.find(h=>h.id==='e').prep=[row('cadence','rear')];savedA.heroes.find(h=>h.id==='e').prep=[row('rhythm','rear')];}
 if(kind==='room'){for(const c of [config,savedA]){c.heroes.forEach(h=>h.defenses.magic='natural');c.heroes.find(h=>h.id==='d').prep=[row('ward','rear')];}config.heroes.find(h=>h.id==='d').overrides.cistern={prep:[row('ward','center')]};scope='cistern';}
 persist();try{localStorage.setItem(storageKey+'-a',JSON.stringify(savedA));}catch{}planner();$('#compare-run').click();tell('示例已载入：A 与 B 只改变所选机制。打开战报查看防御消耗、效果生效或房间覆盖。');}
$('#case-defense').onclick=()=>loadCase('defense');$('#case-delay').onclick=()=>loadCase('delay');$('#case-room').onclick=()=>loadCase('room');

$('#case-summon').onclick=()=>loadCase('summon');$('#case-item').onclick=()=>loadCase('item');

function replaceConfig(next,undo=null){validate(next);undoConfig=undo||configurationUndo(config);config=clone(next);}
function renderPlans(){const select=$('#saved-plans'),chosen=select.value;select.innerHTML='<option value="">选择已保存方案</option>'+plans.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${EXPEDITIONS[p.config.expedition].name}</option>`).join('');if(plans.some(p=>p.id===chosen))select.value=chosen;$('#undo-load').disabled=!undoConfig;$('#undo-load').textContent=undoConfig?.roles?'撤销配置与伙伴职责':'撤销上次载入';$('#undo-description').textContent=undoConfig?.roles?'将恢复载入前配置及'+undoConfig.roles.changes.map(c=>HEROES.find(h=>h.id===c.id).name).join('、')+'的原伙伴职责；期间的训练、装备和其他伙伴调整保留。':'撤销仅保留本次页面会话中最近一次载入前的配置。';$('#plan-count').textContent=plans.length+' / 12 个本机方案';}
function saveNamed(replace){try{const id=replace?$('#saved-plans').value:'plan-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2),next=storePlan(plans,{id,name:$('#plan-name').value,config},replace);localStorage.setItem(plansKey,JSON.stringify({version:1,plans:next}));plans=next;renderPlans();$('#saved-plans').value=id;tell(replace?'所选方案已更新。':'新方案已保存，包含完整房间覆盖与补给。');}catch(e){tell('保存失败：'+e.message);}}
$('#save-plan').onclick=()=>saveNamed(false);$('#update-plan').onclick=()=>saveNamed(true);
$('#saved-plans').onchange=()=>{const p=plans.find(p=>p.id===$('#saved-plans').value);if(p)$('#plan-name').value=p.name;};
$('#load-plan').onclick=()=>{const p=plans.find(p=>p.id===$('#saved-plans').value);if(!p){tell('请先选择一个已保存方案。');return;}replaceConfig(p.config);scope='';persist();planner();tell('已载入「'+p.name+'」，可撤销本次载入。历史战报不变。');};
$('#undo-load').onclick=()=>{if(!undoConfig)return;try{const roles=Boolean(undoConfig.roles),prior=guildUI.undoConfiguration(undoConfig);config=prior.config;undoConfig=null;scope='';if(prior.persisted)savedState();else persist();planner();tell(roles?'已恢复载入前配置与本次改动的伙伴职责；当前训练、装备和其他公会资产保留。':'已恢复载入前的配置。');}catch(e){tell('无法撤销：'+e.message);}};
$('#report-to-a').onclick=()=>{if(!report)return;savedA=clone(report.config);try{localStorage.setItem(storageKey+'-a',JSON.stringify(savedA));}catch{}planner();tell('本次战报的出发配置已设为 A；当前编辑配置保持原样。');};
$('#restore-report').onclick=()=>{if(!report)return;replaceConfig(report.config);scope='';persist();planner();view('planning');tell('已恢复本战报的完整出发配置，可撤销。');};
function renderReview(){
 const rooms=reviewReport(report);$('#review-heading').textContent=EXPEDITIONS[report.config.expedition].name+' · 种子 '+report.config.seed;
 $('#review-rooms').innerHTML=rooms.map(r=>`<details class="review-room" ${r.roomIndex===0?'open':''}><summary>${esc(r.name)} · ${r.won?'通过':'止步'} · ${r.findings.length} 项观察</summary><div class="review-metrics"><span>实扣生命 <b>${r.metrics.damageTaken}</b></span><span>技能治疗 <b>${r.metrics.healing}</b></span><span>道具使用 <b>${r.metrics.items}</b></span><span>空过行动 <b>${r.metrics.failed}</b></span></div><div class="finding-list">${r.findings.map(f=>`<article class="finding ${f.kind}"><h3>${esc(f.title)}</h3><p>${esc(f.fact)}</p><p class="muted">尝试方向：${esc(f.suggestion)}</p><div><button data-evidence="${f.eventIndex}">定位原始事件</button>${f.hero?`<button data-review-edit="${f.roomId}:${f.hero}">从此战报修改 ${heroName(f.hero)}</button>`:''}</div></article>`).join('')||'<p class="muted">未发现当前规则覆盖的观察项；这不代表方案最优。</p>'}</div></details>`).join('');
}
function heroName(id){return HEROES.find(h=>h.id===id)?.name||id;}
$('#review-rooms').onclick=e=>{const evidence=e.target.closest('[data-evidence]'),edit=e.target.closest('[data-review-edit]');if(evidence){stop();$('#diagnostic').checked=true;renderJournal();move(Number(evidence.dataset.evidence));$('.stage').scrollIntoView({block:'start'});}else if(edit)editFromReport(edit.dataset.reviewEdit);};
function comparisonDetails(pair){
 const [a,b]=pair,changes=configurationChanges(a.config,b.config),ra=reviewReport(a),rb=reviewReport(b);
 const cell=(r,key)=>r?(key==='won'?(r.won?'通过':'失败'):key==='hp'||key==='mp'||key==='rounds'?r[key]:['herb','rune','arrow'].includes(key)?r.supplies[key]:r.metrics[key]):'未到达';
 return `<section class="comparison-detail"><h3>配置差异 · ${changes.length} 项</h3><p class="muted">展示上次运行的配置快照；修改配置后请重新对比。按共同种子比较，列出默认值和显式房间覆盖的变化。多个变化同时存在时，结果不能归因于某一个设置。</p>${changes.length?`<div class="table-scroll"><table><thead><tr><th>设置</th><th>A</th><th>B</th></tr></thead><tbody>${changes.map(c=>`<tr><th>${esc(c.label)}</th><td>${esc(c.before)}</td><td>${esc(c.after)}</td></tr>`).join('')}</tbody></table></div>`:'<p>两套配置完全相同。</p>'}${harborReserveComparison(a,b)}<h3>逐房间对照</h3><div class="room-comparison">${roomsFor(a.config).map((room,i)=>`<article><h3>${esc(room.name)}</h3><table><thead><tr><th>观察项</th><th>A</th><th>B</th></tr></thead><tbody>${Object.entries({won:'结果',rounds:'回合',hp:'出房生命',mp:'出房法力',damageTaken:'实扣生命',items:'道具使用',failed:'空过行动',herb:'剩余药草',rune:'剩余符纸',arrow:'剩余箭矢'}).map(([key,label])=>`<tr><th>${label}</th><td>${cell(ra[i],key)}</td><td>${cell(rb[i],key)}</td></tr>`).join('')}</tbody></table></article>`).join('')}</div><p class="muted">出房生命与法力包含此前房间的影响；“实扣生命”只统计本房间正式队员承伤。未到达的房间不记为零。</p></section>`;
}
$('#case-shortage').onclick=()=>loadCase('shortage');

function trainingEditor(h,t,unit){const spent=trainingInvestment(h.training);return `<section class="training-panel"><div class="bar"><h3>实验培养 <small>全局构筑</small></h3><strong>预计 ${spent}经验</strong><button id="clear-training">重置本角色训练</button></div><p class="muted">每项最高+${MAX_TRAINING_RANK}，逐级成本${trainingCostText}经验；无角色总点数硬上限。此处为实验草稿，不扣公会经验；真实出征采用公会实际培养。训练不随房间变化，专修仍可自由调整。</p><div class="training-grid">${Object.entries(trainingOptions(h.id)).map(([key,o])=>{const rank=h.training[key]||0,spec=(o.kind==='skill'?h.trained:h.defenseFocus)===o.id?3:0,level=t.base+spec+rank,disabled=rank>=MAX_TRAINING_RANK;return `<article class="training-row"><div><b>${esc(o.name)}</b><span>${o.kind==='skill'?'职业技能':'防御技能'} · 静态等级 ${level}</span><small>基础 ${t.base} + 专修 ${spec} + 训练 ${rank}${o.kind==='skill'?' · 检定均值 '+mean(unit,o.id):''}</small>${o.kind==='skill'&&SKILLS[o.id].requiresGear?'<small class="'+(gearSupports(h.gear,SKILLS[o.id].requiresGear)?'':'gear-warning')+'">需要 '+gearRequirementName(SKILLS[o.id].requiresGear)+'</small>':''}</div><div class="training-controls"><button data-training="${key}" data-delta="-1" ${rank===0?'disabled':''} aria-label="减少${o.name}训练">−</button><strong>+${rank}</strong><button data-training="${key}" data-delta="1" ${disabled?'disabled':''} aria-label="增加${o.name}训练">＋</button><small>${rank===MAX_TRAINING_RANK?'已达上限':'下一级 '+((rank+1)*TRAINING_XP_UNIT)+'经验'}</small></div></article>`;}).join('')}</div><p class="muted">以上为出发前等级，临时效果另算。固定数值技能（如远征药膳）不会因训练提高效果；请结合技能说明与实战记录分配。</p></section>`;}
for(const kind of ['balanced','support','defense'])$('#build-'+kind).onclick=()=>{replaceConfig(trainingBuild(kind));scope='';persist();planner();view('planning');tell('训练方案已载入，包含潮汐异变战术。可撤销本次载入，或保存到方案册后继续调整。');};
$('#case-training').onclick=()=>loadCase('training');$('#case-pierce').onclick=()=>loadCase('pierce');

function renderIntel(){
 $('#intel-route').textContent=EXPEDITIONS[config.expedition].name;
 $('#intel').innerHTML=roomsFor(config).map((r,i)=>`<article class="encounter-card"><div class="encounter-heading"><small>ENCOUNTER 0${i+1}</small><h3>${esc(r.name)}</h3><span>${r.enemies.length} 名敌人 · ${new Set(r.enemies.map(e=>e.pos)).size} 个阵位</span></div><p>${esc(r.note)}</p><div class="enemy-dossier">${r.enemies.map(u=>`<details><summary><b>${esc(u.name)}</b><span>${POS[u.pos]} · ${u.maxHp} HP</span></summary><div class="enemy-facts"><span>护甲 <b>${current(u,'armor')}</b></span>${Object.entries(TYPES).map(([k,v])=>{const n=resistanceOf(u,k);return `<span class="${n>0?'resist':n<0?'vulnerable':''}">${v} ${n<0?'弱点':'抗性'} <b>${Math.abs(n)}%</b></span>`;}).join('')}</div><p><small>预备：${u.prep.length?u.prep.map(r=>SKILLS[r.skill].name+' → '+(POS[r.target]||'自身')).join('；'):'无'}${u.healing?.enabled?'<br>治疗：'+Math.round(u.healing.threshold*100)+'% · 最低生命比例 · 全队 · 等级 '+u.skills.heal+' · 每次5法力/1药草':''}<br>普通：${u.main.map(r=>SKILLS[r.skill].name+' → '+POS[r.target]+' · 等级 '+u.skills[r.skill]+' / 均值 '+mean(u,r.skill)).join('；')}</small></p></details>`).join('')}</div><button data-intel-room="${r.id}">配置这个房间</button></article>`).join('');
}
