function renderDeparture(){
 const isChapter=config.expedition==='chapter',isArchive=hasArchiveEvents(config),units=buildParty(config),b=BELL_CHOICES[config.bellApproach];
 $('#departure-overview').innerHTML=`<p class="eyebrow">出发计划 / ${esc(EXPEDITIONS[config.expedition].name)}</p><h2>先看整条远征，再分配每一份资源。</h2><div class="departure-cards"><article><small>01 · 携带补给</small><h3>${config.supplies.herb} 药草 / ${config.supplies.rune} 符纸 / ${config.supplies.arrow} 箭矢</h3><p>房间之间延续生命、法力与物资。</p><button data-prep-jump="team">配置队伍与补给 →</button></article><article><small>02 · 回廊事件</small><h3>${config.expedition==='harbor'?HARBOR_PASS[config.harbor.pass]+' → '+HARBOR_TASK[config.harbor.task]:isArchive?RESCUE_CHOICES[config.rescueApproach].name+' → '+b.name:'本路线无回廊事件'}</h3><p>${isArchive?'先救援，所得物资可用于沉钟；检定使用实际进场状态。':'按各场敌情配置技能、阵位与协作顺序。'}</p><button data-prep-jump="events">查看事件策略 →</button></article><article><small>03 · ${isChapter?'封库出口与下半章':'最终遭遇'}</small><h3>${isArchive?(config.bellApproach==='study'?'成功解读 → 破印路线':config.bellApproach==='force'?'成功破拆 → 侧门路线':'按计划走正门'):'按敌情进入末房'}</h3><p>${isArchive?(isChapter?'成功改变第三场封库出口；之后仍须带着剩余资源走完三场疗所遭遇。':'只有成功才改变末房；失败、缺料或无执行者仍走正门。'):'保留足够补给，避免末房空过行动。'}</p><button data-prep-jump="plans">管理完整方案 →</button></article></div><p class="muted">当前药师治疗均值 ${units.some(u=>u.skills.heal!==undefined)?Math.max(...units.filter(u=>u.skills.heal!==undefined).map(u=>mean(u,'heal'))):'无可用药师'}。这里只展示出发计划，不预测实际成功或改写已有战报。</p>`;
}
