function renderSettlement(){
 const contract=contractResult(report);$('#contract-outcome').hidden=!contract;if(contract)$('#contract-outcome').innerHTML=`<p class=eyebrow>疗所委托 / 完整结算</p><h2>${contract.handoff?'药箱按时抵岸，六人一同归来。':contract.cargo?'物资完整归航，交接稍晚。':'远征已结算，封存目标尚未完成。'}</h2><div class=departure-cards><article><h3>封存物资 ${contract.cargo?'✓':'未达成'}</h3><p>符纸 ${report.supplies.rune}/4 · 箭矢 ${report.supplies.arrow}/4 · ${contract.alive}/6 人存活</p></article><article><h3>准时交接 ${contract.handoff?'✓':'未达成'}</h3><p>三房累计 ${contract.rounds}/15 回合；须同时完成封存目标。</p></article></div><button data-contract=opening>调整为每房开场爆发</button><p class=muted>此处为完整结算，不随回放变化。下方战场任务条只显示播放到当前事件时的情况。委托暂不发放成长奖励。</p>`;
 const ledger=supplyLedger(report);
 $('#settlement').innerHTML='<p class="eyebrow">完整远征结算 / 包含尚未播放的结果</p><div class="departure-cards">'+settlementGoals(report).map(g=>`<article class="goal ${g.done?'achieved':''}"><small>${g.done?'已达成':'未达成'}</small><h3>${g.name}</h3><p>${g.rule}</p></article>`).join('')+'</div><h3>共享补给收支</h3><table><thead><tr><th>物资</th><th>出发</th><th>获得</th><th>消耗</th><th>剩余</th></tr></thead><tbody>'+ledger.rows.map(r=>`<tr><td>${r.name}</td><td>${r.start}</td><td>+${r.gained}</td><td>−${r.spent}</td><td>${r.end}</td></tr>`).join('')+'</tbody></table><p class="muted">出发＋获得−消耗＝剩余。仅统计共享物资，不含法力或随身道具次数。目标无成长奖励，物资不会带入下次远征。</p><details><summary>逐笔变动 · '+ledger.entries.length+' 条（点击追溯战报）</summary><div class="ledger-entries">'+ledger.entries.map(x=>`<button data-ledger-event="${x.eventId}"><small>${x.roomIndex+1}房 / 回合${x.round} · ${x.changes.map(c=>c.name+' '+(c.delta>0?'+':'')+c.delta).join(' / ')}</small><span>${esc(x.text)}</span></button>`).join('')+'</div></details>';
}
