function healingBlockMarkup(block){const origin=block?originMap.get(block.effectId):null,canTrace=origin&&origin.source===block.source&&origin.targets.includes(block.target)&&origin.index<index,roomId=canTrace?roomsFor(report.config)[report.events[origin.index].roomIndex]?.id:null,canEdit=roomId&&report.config.heroes.some(h=>h.id===block.source);return `<p class="healing-block-proof">禁疗仅限制本回合余下的自动草药救护；不会撤销已完成治疗，也不会阻止普通指令。${canTrace?`<button data-healing-origin="${origin.index}">查看禁疗命中来源 →</button>`:''}${canEdit?`<button data-healing-edit="${roomId}:${block.source}">调整本房截疗指令 →</button><small>改配用于准备页与A/B实验；公会仍按已应用伙伴职责执行，请核对实际指令。</small>`:''}</p>`;}
function healingMarkup(d){
 const skipped=d.status==='item_priority';

 return `<section class="healing-decision"><h4>治疗决策 · ${esc(healingReason(d))}</h4>${d.status==='blocked'?healingBlockMarkup(d.block):''}<p>策略：${esc(HEAL_PRIORITIES[d.selectionPolicy||'lowest'])}。行动开始：MP ${d.mp} / 需要${d.cost.mp} · 药草 ${d.herb} / 需要${d.cost.herb} · 阈值 ${Math.round(d.threshold*100)}% · 范围 ${esc(POS[d.target]||({all:'全队',self:'自身'}[d.target])||d.target)}</p>${skipped?'<p>道具优先并占用行动；以下治疗候选未参与本次决策。</p>':`<div class="table-scroll"><table><thead><tr><th>队员</th><th>检查时生命</th><th>生命比例</th><th>资格</th></tr></thead><tbody>${d.candidates.map(x=>`<tr><th>${esc(x.name)}${x.id===d.selectedId?' · 优先候选':''}</th><td>${x.hp}/${x.maxHp}</td><td>${(x.ratio*100).toFixed(1)}%</td><td>${esc(x.reason)}</td></tr>`).join('')}</tbody></table></div><small>${esc(d.priority)}${!d.enabled?' 自动治疗关闭时以上仅为状态快照，不执行选择。':''}</small>`}</section>`;
}

