function renderDeployment(){
 const v=deploymentPreview(config,scope),coverage=v.coverage.find(x=>x.id===coverageId)||v.coverage[0],active=v.units.find(u=>u.id===selected),roomInfo=roomsFor(config).find(r=>r.id===scope);
 if(coverage)coverageId=coverage.id;
 $('#deployment').innerHTML=`<div class="bar"><div><p class=eyebrow>部署桌 / 站位与协作覆盖</p><h2>把队员放在能相互照应的位置。</h2></div><label>编辑范围<select id="deploy-scope"><option value="">默认方案</option>${roomsFor(config).map(r=>`<option value="${r.id}" ${r.id===scope?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label></div><p>${roomInfo?esc(roomInfo.note):'默认站位供未单独覆盖的房间继承。切换房间可查看该房间实际采用的配置。'}</p><div class="deployment-layout"><div><div class="deploy-selection">已选 <strong>${esc(active.name)}</strong> · ${POS[active.pos]} · ${active.overridden?'本房覆盖':scope?'继承默认':'默认站位'} ${active.overridden?'<button data-inherit="pos">恢复默认站位</button>':''}<span>点击队员选中，再点击阵位下方的部署按钮。</span></div><div class="deployment-board">${Object.entries(POS).map(([pos,label])=>`<section class="deploy-zone deploy-${pos}"><div class="bar"><strong>${label}</strong><small>${v.units.filter(u=>u.pos===pos).length} 人</small></div><div class="deploy-units">${v.units.filter(u=>u.pos===pos).map(u=>`<button data-hero="${u.id}" class="deploy-unit ${selected===u.id?'selected':''} ${coverage?.recipients.includes(u.id)?'covered':''}" aria-pressed="${selected===u.id}" aria-label="选择${esc(u.name)}"><span class="portrait ${portrait(u)}" aria-hidden="true"></span><b>${esc(u.name)}</b><small>${u.overridden?'房间覆盖':'默认'}${coverage?.recipients.includes(u.id)?' · 可覆盖':''}</small></button>`).join('')||'<small class="muted">暂无队员</small>'}</div><button class="deploy-place" data-deploy="${pos}" ${active.pos===pos?'disabled':''}>部署至${label}</button></section>`).join('')}</div></div><aside class="coverage-preview"><h3>辅助覆盖候选</h3><p class="muted">点击一条预备指令，高亮其可覆盖的正式队员。</p>${v.coverage.map(x=>`<button data-coverage="${x.id}" aria-pressed="${coverage?.id===x.id}"><strong>${esc(x.name)} · ${SKILLS[x.skill].name}</strong><small>预备第${x.row+1}条 → ${POS[x.target]||({self:'自身',all:'全队'}[x.target])} · ${x.recipients.length} 人</small></button>`).join('')||'<p>当前未配置辅助技能。</p>'}<div class="coverage-result" aria-live="polite"><strong>${coverage?SKILLS[coverage.skill].name:'无辅助指令'}</strong><p>${coverage?.recipients.length?coverage.recipients.map(id=>HEROES.find(h=>h.id===id).name).join('、'):'没有覆盖候选'}</p></div><small>按出发时全员存活、无临时效果计算；同位置上限按技能规则。不模拟指令轮转、材料、法力、同名效果互斥或后续召唤物，不保证实际施放成功。</small></aside></div><div class="deploy-order"><span>回合前顺序</span>${v.order.map((id,i)=>`<button data-hero="${id}">${i+1} · ${HEROES.find(h=>h.id===id).name}</button>`).join('')}</div><p class="muted">阵位是逻辑分组，不代表距离。普通行动先攻另行检定；辅助先后顺序在下方调整。移动不会改写已经生成的战报。</p>`+cooperationView(cooperationCheck(config,scope));
}

