window.addEventListener('resize',()=>{if(report&&document.body.dataset.view==='replay')drawFx(stageFrame(selectedGroup()));});

$('#personal-playback').onchange=syncPersonalReplay;

function renderHarborPlan(){const enabled=config.expedition==='harbor';$('#harbor-plan').hidden=!enabled;$('#harbor-plan').innerHTML=harborPlanView(config);$('#harbor-brief').hidden=!enabled;$('#harbor-brief').innerHTML=enabled?'<p class="eyebrow">第二章 / 自动分支</p><h2>盐风港的无光灯塔</h2><p>每次四场战斗；通路与港口事件在抵达时按队伍状态执行。先在事件策略查看全部分支和条件，再核对实际公会装备。</p><button id="open-harbor-plan">查看港口分支计划 →</button>':'';}
$('#harbor-plan').onchange=e=>{if(e.target.dataset.harbor){config.harbor[e.target.dataset.harbor]=e.target.value;persist();planner();tell('港口策略已保存；实际结果将在远征抵达该节点时结算。');}};
$('#harbor-brief').onclick=e=>{if(e.target.id==='open-harbor-plan'){setPrep('events');$('#harbor-plan').scrollIntoView({block:'start'});}};
for(const el of [$('#harbor-journey'),$('#event-scene'),$('#harbor-assessment')])el.addEventListener('click',e=>{const b=e.target.closest('[data-harbor-source]');if(b){stop();move(report.events.findIndex(x=>x.id===Number(b.dataset.harborSource)));$('.stage').scrollIntoView({block:'start'});}});

$('#harbor-plan').onclick=e=>{const b=e.target.closest('[data-harbor-tactics]');if(!b)return;replaceConfig(applyHarborTactics(config,b.dataset.harborTactics));persist();planner();tell('已应用'+HARBOR_TACTICS[b.dataset.harborTactics].name+'；请核对公会实际指令，可在方案管理撤销。');};

function editFromReport(target){const [roomId,hero]=target.split(':');replaceConfig(report.config);savedA=clone(report.config);try{localStorage.setItem(storageKey+'-a',JSON.stringify(savedA));}catch{}scope=roomId;selected=hero;persist();planner();view('planning');setPrep('team');$('#editor').scrollIntoView({block:'start'});tell('已从战报出发配置开始修改，并将它冻结为 A。当前仅定位到该队员与房间，尚未自动修改任何战术。');}
$('#harbor-assessment').addEventListener('click',e=>{const source=e.target.closest('[data-ledger-source]'),edit=e.target.closest('[data-review-edit]');if(source){stop();$('#highlights-only').checked=false;$('#diagnostic').checked=true;replayWorkspace.open('evidence');renderJournal();move(report.events.findIndex(x=>x.id===Number(source.dataset.ledgerSource)));$('#detail').scrollIntoView({block:'start'});}else if(edit)editFromReport(edit.dataset.reviewEdit);});

function openSupportEvidenceEvent(value){const at=report?.events.findIndex(e=>e.id===Number(value));if(at===undefined||at<0)return;stop();supportEvidenceReturn=true;traceReturn=null;$('#highlights-only').checked=false;$('#diagnostic').checked=true;replayWorkspace.open('evidence');renderJournal();move(at);$('#detail').scrollIntoView({block:'start'});}
$('#support-evidence').onclick=e=>{const source=e.target.closest('[data-support-evidence-event]'),edit=e.target.closest('[data-support-evidence-edit]');if(source)openSupportEvidenceEvent(source.dataset.supportEvidenceEvent);else if(edit)editFromReport(edit.dataset.supportEvidenceEdit);};
$('#support-evidence').onchange=e=>{if(e.target.id==='support-evidence-actor')$('#support-evidence').innerHTML=supportEvidenceView(supportEvidenceData,e.target.value);else if(e.target.matches('[data-support-evidence-record]')&&e.target.value)openSupportEvidenceEvent(e.target.value);};

$('#replay').addEventListener('click',e=>{const edit=e.target.closest('[data-healing-edit]');if(edit){editFromReport(edit.dataset.healingEdit);return;}const b=e.target.closest('[data-healing-origin]');if(!b)return;const at=Number(b.dataset.healingOrigin);if(!Number.isInteger(at)||!report?.events[at])return;traceReturn=index;stop();$('#highlights-only').checked=false;$('#diagnostic').checked=true;replayWorkspace.open('evidence');renderJournal();move(at);$('#support-focus').scrollIntoView({block:'start'});});
